; rotor2_test.asm - generated by make_rotor_test.py: three 4-blade rotors spinning at 2, 5 and 9 / 64 turns per frame.
; Build: lwasm --format=raw -o rotor_test_raw.bin rotor2_test.asm, then pad to 32768 bytes with $FF.

Wait_Recal      equ $F192
Intensity_a     equ $F2AB
Moveto_d        equ $F312
Draw_Line_d     equ $F3DF
Reset0Ref       equ $F354

Angles          equ $C880           ; one byte per rotor
Blade           equ $C884           ; the blade's angle now
Count           equ $C885
Tmp             equ $C886

        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$40
        fcc     "ROTOR TEST 2"
        fcb     $80
        fcb     0

Start:
        clr     Angles
        clr     Angles+1
        clr     Angles+2
Main:
        jsr     Wait_Recal
        lda     #$7F
        jsr     Intensity_a
; rotor 0
        jsr     Reset0Ref
        lda     #$7F
        sta     $D004
        lda     #40
        ldb     #-70
        jsr     Moveto_d
        lda     #$30
        sta     $D004
        lda     Angles+0
        adda    #2
        anda    #63
        sta     Angles+0
        sta     Blade
        lda     #4
        sta     Count
        jsr     Rotor
; rotor 1
        jsr     Reset0Ref
        lda     #$7F
        sta     $D004
        lda     #40
        ldb     #70
        jsr     Moveto_d
        lda     #$30
        sta     $D004
        lda     Angles+1
        adda    #5
        anda    #63
        sta     Angles+1
        sta     Blade
        lda     #4
        sta     Count
        jsr     Rotor
; rotor 2
        jsr     Reset0Ref
        lda     #$7F
        sta     $D004
        lda     #-55
        ldb     #0
        jsr     Moveto_d
        lda     #$30
        sta     $D004
        lda     Angles+2
        adda    #9
        anda    #63
        sta     Angles+2
        sta     Blade
        lda     #4
        sta     Count
        jsr     Rotor
        jmp     >Main               ; (extended: Main sits below $100 and DP is $D0)

; the four blades from the beam's place now (the hub): out along a blade, back to the hub with the beam off
Rotor:
        lda     Blade
        lsla
        ldx     #Tips
        leax    a,x
        ldd     ,x
        clr     $C823               ; Vec_Misc_Count: one line only
        jsr     Draw_Line_d
        lda     Blade
        lsla
        ldx     #Back
        leax    a,x
        ldd     ,x
        std     Tmp
        lda     Blade
        lsla
        ldx     #Perp
        leax    a,x
        ldd     ,x
        jsr     Moveto_d            ; across to the blade's second line
        ldd     Tmp
        clr     $C823
        jsr     Draw_Line_d         ; back to the hub, beside the first
        lda     Blade
        lsla
        ldx     #NPerp
        leax    a,x
        ldd     ,x
        jsr     Moveto_d            ; across back to the hub
        lda     Blade
        adda    #16
        anda    #63
        sta     Blade
        dec     Count
        bne     Rotor
        rts

